+
+/**
+ * Asks the HDMI-CEC device on the given connector, usually a TV, to turn on
+ * and switch to our input ("One Touch Play"). This happens asynchronously and
+ * silently does nothing if the connector has no CEC adapter we can access.
+ */
+void cecOneTouchPlay(dev_t drmDevice, uint32_t connectorId);
+
+}
