index 3cab4c13b6..9b8ef98ee6 100644
--- a/src/backends/drm/drm_output.cpp
+++ b/src/backends/drm/drm_output.cpp
@@ -8,6 +8,7 @@
 */
 #include "drm_output.h"
 #include "drm_backend.h"
+#include "drm_cec.h"
 #include "drm_connector.h"
 #include "drm_crtc.h"
 #include "drm_gpu.h"
@@ -667,6 +668,10 @@ void DrmOutput::applyQueuedChanges(const std::shared_ptr<OutputChangeSet> &props
             m_renderLoop->inhibit();
         }
     }
+    const bool wasOn = m_state.enabled && m_state.dpmsMode == DpmsMode::On;
+    if (!wasOn && m_nextState->enabled && m_nextState->dpmsMode == DpmsMode::On) {
+        cecOneTouchPlay(m_gpu->drmDevice()->deviceId(), m_connector->id());
+    }
     setState(*m_nextState);
     m_nextState.reset();

